-- Paket ABT "abt-identitas-pihak-1nov" (1 Nov 2026, agen V; keputusan pengguna 101 dan 102): format identitas pihak putusan/penetapan = blangko acuan "[01] [Kabul Verstek] Cerai (Format Lengkap)".
-- Variabel 7047, 7048 dan fungsi isian_rtf_pihak_identitas, isian_rtf_pihak_tambahan diubah; blangko RTF lewat daftar-tambal.tsv/tambal.tsv. Hanya pengguna derry_briantono. Prasyarat: paket ke-30 (perbaikan-1nov) terpasang.
-- PRASYARAT (baca saja) "A|B|C|D|E|F": A = fungsi identitas/tambahan yang isinya persis keadaan server (2 pertama, 0 ulang) | B = yang sudah isi BARU paket ini (0 pertama, 2 ulang) | C = dari 2 variabel (7047,7048) yang masih isi LAMA (2 pertama, 0 ulang) | D = yang sudah isi BARU (0 pertama, 2 ulang) | E = baris variabel diubah yang bukan lama bukan baru, ditambah fungsi identitas/tambahan yang bukan lama bukan baru (harus 0) | F = fungsi pendukung yang harus ada (6).
-- Benar: "2|0|2|0|0|6" (pertama) atau "0|2|0|2|0|6" (pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4c758ce53cd541a39a32cf3cb0ba9898') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='9cf2a80618cfee32d3b096c4b1c83dc8'))), '|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='113ebf541054dcd26ae71eda56a50298') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='d4f6b5867b95ce1304858b49e12c1459'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='e301c4feae2efcb0794fdff285d8f155') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='f9552a7f198356fd6394e7c212bdfc37'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='94f40d4f4bd51b9fab75184521617176') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='0424f2f0336893a1b4080e660d707361'))), '|', ((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (7047,7048) AND NOT (((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='e301c4feae2efcb0794fdff285d8f155') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='f9552a7f198356fd6394e7c212bdfc37')) OR ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='94f40d4f4bd51b9fab75184521617176') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='0424f2f0336893a1b4080e660d707361')))) + (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name IN ('isian_rtf_pihak_identitas','isian_rtf_pihak_tambahan') AND NOT (((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4c758ce53cd541a39a32cf3cb0ba9898') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='9cf2a80618cfee32d3b096c4b1c83dc8')) OR ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='113ebf541054dcd26ae71eda56a50298') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='d4f6b5867b95ce1304858b49e12c1459'))))), '|', (SELECT COUNT(DISTINCT routine_name) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name IN ('isian_rtf_pihak_jumlah','isian_rtf_romawi','isian_rtf_tanggal','isian_rtf_alamat_putusan','isian_rtf_alamat','isian_rtf_identitas_kosong'))) AS prasyarat;
